#!/usr/bin/env python3
"""Generate a multi-module Ballerina package whose functions call generic
langlib functions (push/indexOf/map/clone/map:get) that the type resolver
monomorphizes per call site.

usage: gen_mono.py <outdir> <modules> <funcs_per_module> [--control]

--control replaces each generic langlib call with a call to an equivalent
non-generic user function, keeping the program shape identical.
"""
import os, sys, shutil

out, M, F = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
control = "--control" in sys.argv
shutil.rmtree(out, ignore_errors=True)
os.makedirs(out)
open(os.path.join(out, "Ballerina.toml"), "w").write(
    '[package]\norg = "perf"\nname = "mono"\nversion = "0.1.0"\n')

helpers = """
function myClone(int[] a) returns int[] => [...a];
function myPush(int[] a, int v) { a[a.length()] = v; }
function myIndexOf(int[] a, int v) returns int? => a.length() > v ? 0 : ();
function myGet(map<int> m, string k) returns int => m.hasKey(k) ? 1 : 0;
"""

def body(k):
    if control:
        return f"""    int[] ys = myClone(xs);
    myPush(ys, {k});
    myPush(ys, {k + 1});
    int[] zs = ys;
    int i = myIndexOf(zs, {k}) ?: 0;
    int v = myGet(m, "a");
    return i + v + zs.length();"""
    return f"""    int[] ys = xs.clone();
    ys.push({k});
    ys.push({k + 1});
    int[] zs = ys;
    int i = zs.indexOf({k}) ?: 0;
    int v = m.get("a");
    return i + v + zs.length();"""

for mi in range(M):
    d = os.path.join(out, "modules", f"m{mi}")
    os.makedirs(d)
    src = [helpers] if control else []
    for fi in range(F):
        src.append(f"public function f{fi}(int[] xs, map<int> m) returns int {{\n{body(fi)}\n}}\n")
    open(os.path.join(d, f"m{mi}.bal"), "w").write("\n".join(src))

main = ["import ballerina/io;"]
main += [f"import perf/mono.m{mi};" for mi in range(M)]
main.append("public function main() {\n    int[] xs = [1, 2, 3];\n    map<int> m = {a: 1};\n    int s = 0;")
main += [f"    s += m{mi}:f0(xs, m);" for mi in range(M)]
main.append("    io:println(s);\n}")
open(os.path.join(out, "main.bal"), "w").write("\n".join(main) + "\n")

