+// shapeHashDepth bounds how many atoms deep ShapeHash looks, which also stops
+// it on recursive types.
+const shapeHashDepth = 4
+
+const (
+	shapeHashOffset uint64 = 14695981039346656037
+	shapeHashPrime  uint64 = 1099511628211
+)
+
+// ShapeHash returns a hash of ty's structure that ignores atom identity: types
+// for which IsSameShape holds hash equal. Equal hashes imply nothing, so a
+// caller must confirm a match with IsSameShape.
+func ShapeHash(cx Context, ty SemType) uint64 {
+	return shapeHash(cx, ty, shapeHashDepth)
+}
+
+func shapeHashMix(h, v uint64) uint64 {
+	return (h ^ v) * shapeHashPrime
+}
+
+func shapeHash(cx Context, ty SemType, depth int) uint64 {
+	h := shapeHashMix(shapeHashMix(shapeHashOffset, uint64(ty.all())), uint64(ty.some()))
+	if depth == 0 || ty.some() == 0 {
+		return h
+	}
+	for _, sub := range unpack(ty) {
+		if b, ok := sub.subtypeData.(bdd); ok {
+			h = shapeHashMix(h, bddShapeHash(cx, sub.basicTypeCode, b, depth))
+		}
+	}
+	return h
+}
+
+func bddShapeHash(cx Context, code basicTypeCode, b bdd, depth int) uint64 {
+	switch b := b.(type) {
+	case *bddAllOrNothing:
+		if b.isAll {
+			return 1
+		}
+		return 2
+	case bddNode:
+		h := shapeHashMix(shapeHashOffset, atomShapeHash(cx, code, b.atom(), depth-1))
+		h = shapeHashMix(h, bddShapeHash(cx, code, b.left(), depth))
+		h = shapeHashMix(h, bddShapeHash(cx, code, b.middle(), depth))
+		return shapeHashMix(h, bddShapeHash(cx, code, b.right(), depth))
+	default:
+		return 0
+	}
