+
+// shapeAtomicType returns the atomic type of atom, an atom of a BDD of basic
+// type code. A rec atom's atomic type is found through the env table of code;
+// it is nil for a rec atom of a basic type whose table is not known here, for
+// one with a reserved index, and for one not yet defined.
+func shapeAtomicType(cx Context, code basicTypeCode, a atom) AtomicType {
+	switch a := a.(type) {
+	case *typeAtom:
+		return a.AtomicType
+	case *recAtom:
+		if a.index() < 0 {
+			return nil
+		}
+		switch code {
+		case btList:
+			if atomic := cx.ListAtomType(a); atomic != nil {
+				return atomic
+			}
+		case btMapping:
+			if atomic := cx.MappingAtomType(a); atomic != nil {
+				return atomic
+			}
+		case btFunction:
+			if atomic := cx.FunctionAtomType(a); atomic != nil {
+				return atomic
+			}
+		}
+	}
+	return nil
