+	case *ListAtomicType:
+		h = shapeHashMix(h, uint64(atomic.members.FixedLength))
+		for _, member := range atomic.members.initial {
+			h = shapeHashMix(h, shapeHash(cx, member, depth))
+		}
+		return shapeHashMix(h, shapeHash(cx, atomic.rest, depth))
+	case *MappingAtomicType:
+		for i, name := range atomic.names {
+			h = shapeHashMix(h, stringShapeHash(name))
+			h = shapeHashMix(h, shapeHash(cx, atomic.types[i], depth))
+		}
