+	case *functionAtomicType:
+		h = shapeHashMix(h, shapeHash(cx, atomic.ParamType, depth))
+		h = shapeHashMix(h, shapeHash(cx, atomic.RetType, depth))
+		return shapeHashMix(h, shapeHash(cx, atomic.Qualifiers, depth))
+	case *cellAtomicType:
+		return shapeHashMix(shapeHashMix(h, uint64(atomic.Mut)), shapeHash(cx, atomic.Ty, depth))
