+// IsSameShape reports whether t1 and t2 have the same structure, ignoring atom
+// identity: two types built separately from the same type descriptor have the
+// same shape although they do not share atoms. Types of the same shape are the
+// same type. It may report false for types of the same
+// shape whose structure it does not compare, such as ones with singleton int,
+// float, decimal or string members.
+func IsSameShape(cx Context, t1, t2 SemType) bool {
+	s := shapeComparison{cx: cx, assumed: make(map[[2]atomKey]bool)}
+	return s.sameSemType(t1, t2)
