+
+// shapeComparison compares the shapes of two types. assumed holds the pairs of
+// atoms already compared or being compared further up the walk; a recursive
+// type reaches such a pair again, and treating it as equal makes the comparison
+// a bisimulation. A pair that turns out to differ fails the whole comparison,
+// so an assumption is never relied on after it is refuted.
+type shapeComparison struct {
+	cx      Context
+	assumed map[[2]atomKey]bool
+}
+
+func (s *shapeComparison) sameSemType(t1, t2 SemType) bool {
+	if t1.all() != t2.all() || t1.some() != t2.some() {
+		return false
+	}
+	if t1.some() == 0 {
+		return true
+	}
+	subs1, subs2 := unpack(t1), unpack(t2)
+	for i := range subs1 {
+		b1, ok1 := subs1[i].subtypeData.(bdd)
+		b2, ok2 := subs2[i].subtypeData.(bdd)
+		if !ok1 || !ok2 {
+			if !sameSubtypeData(subs1[i].subtypeData, subs2[i].subtypeData) {
+				return false
+			}
+			continue
+		}
+		if !s.sameBdd(subs1[i].basicTypeCode, b1, b2) {
+			return false
+		}
+	}
+	return true
+}
+
+func (s *shapeComparison) sameBdd(code basicTypeCode, b1, b2 bdd) bool {
+	if b1.canonicalKey() == b2.canonicalKey() {
+		return true
+	}
+	n1, ok1 := b1.(bddNode)
+	n2, ok2 := b2.(bddNode)
+	if !ok1 || !ok2 {
+		return false
+	}
+	return s.sameAtom(code, n1.atom(), n2.atom()) &&
+		s.sameBdd(code, n1.left(), n2.left()) &&
+		s.sameBdd(code, n1.middle(), n2.middle()) &&
+		s.sameBdd(code, n1.right(), n2.right())
+}
+
+func (s *shapeComparison) sameAtom(code basicTypeCode, a1, a2 atom) bool {
+	pair := [2]atomKey{a1.canonicalKey(), a2.canonicalKey()}
+	if pair[0] == pair[1] || s.assumed[pair] {
+		return true
+	}
+	atomic1, atomic2 := shapeAtomicType(s.cx, code, a1), shapeAtomicType(s.cx, code, a2)
