+		return false
+	}
+	s.assumed[pair] = true
+	return s.sameAtomicType(atomic1, atomic2)
+}
+
+func (s *shapeComparison) sameAtomicType(atomic1, atomic2 AtomicType) bool {
+	switch atomic1 := atomic1.(type) {
+	case *ListAtomicType:
+		atomic2, ok := atomic2.(*ListAtomicType)
+		return ok && atomic1.members.FixedLength == atomic2.members.FixedLength &&
+			s.sameSemTypes(atomic1.members.initial, atomic2.members.initial) &&
+			s.sameSemType(atomic1.rest, atomic2.rest)
+	case *MappingAtomicType:
+		atomic2, ok := atomic2.(*MappingAtomicType)
+		return ok && slices.Equal(atomic1.names, atomic2.names) &&
+			s.sameSemTypes(atomic1.types, atomic2.types) &&
+			s.sameSemType(atomic1.rest, atomic2.rest)
+	case *functionAtomicType:
+		atomic2, ok := atomic2.(*functionAtomicType)
+		return ok && atomic1.IsGeneric == atomic2.IsGeneric &&
+			s.sameSemType(atomic1.ParamType, atomic2.ParamType) &&
+			s.sameSemType(atomic1.RetType, atomic2.RetType) &&
+			s.sameSemType(atomic1.Qualifiers, atomic2.Qualifiers)
+	case *cellAtomicType:
+		atomic2, ok := atomic2.(*cellAtomicType)
+		return ok && atomic1.Mut == atomic2.Mut && s.sameSemType(atomic1.Ty, atomic2.Ty)
