+		return false
+	}
+}
+
+func (s *shapeComparison) sameSemTypes(types1, types2 []SemType) bool {
+	if len(types1) != len(types2) {
+		return false
+	}
+	for i := range types1 {
+		if !s.sameSemType(types1[i], types2[i]) {
+			return false
+		}
+	}
+	return true
+}
